import {forestJourney,decorations,decorateForest} from './forest.js';

const asset=(id,cls='',style='')=>`<img src="assets/forest/${id}.webp" class="${cls}" style="${style}" alt="" loading="lazy" draggable="false">`;
export function forestScene(s,area=forestJourney(s).area){const j=forestJourney(s),past=area<j.area,local=past?20:j.local,stage=past?4:j.stage;
 const trees=['tree_symbol_stage_01','tree_symbol_stage_02','tree_symbol_stage_03','tree_symbol_stage_04','tree_symbol_01'];
 return `<div class="forest-scene" role="img" aria-label="${area+1}番目の森。${['芽','苗木','若木','大きな木','花咲く木'][stage]}${local>=8?'。池ができた':''}${local>=12?'。動物が遊びに来た':''}">${asset('tree_pine_01','forest-back','left:0;')}${asset('tree_birch_01','forest-back','right:0;')}${local>=8?asset('pond_medium_01','forest-pond'):''}${local>=10?asset('bridge_medium_01','forest-bridge'):''}${asset(trees[stage],'forest-tree')}${local>=12?asset('rabbit_01','forest-animal'):''}${local>=16?asset('squirrel_01','forest-squirrel'):''}${(j.flowers||j.variety)?asset('flower_patch_01','forest-flowers'):''}${Array.from({length:6},(_,i)=>{const id=j.decor[`${area}:${i}`];return id?asset(id,'forest-decoration',`left:${12+(i%3)*32}%;top:${68+Math.floor(i/3)*17}%;`):'';}).join('')}<span class="forest-glints" aria-hidden="true">✦ · ✧</span></div>`;
}
export function forestSummary(s){const j=forestJourney(s);return `<div class="forest-summary"><strong>今日 ${Math.floor(j.today/5)}ラウンド・${j.today}問に挑戦</strong><span>あと${j.untilWater}問で水と ✦3スター</span><progress value="${j.water}" max="5" aria-label="次の水まで ${j.water}/5問"></progress><small>水 ${j.rounds}回 · 苦手を克服した花 ${j.flowers}こ · ${j.area+1}番目の森</small></div>`;}
export function forestHome(s){return `<section class="panel forest-home"><div class="section-head"><div><small class="eyebrow">YOUR ENGLISH FOREST</small><h2>学ぶたび、育つ森。</h2></div><a class="pill" href="#forest">森を見る →</a></div>${forestScene(s)}${forestSummary(s)}<button class="primary start" data-forest-start="read" ${s.fast?.round&&s.fast.index<s.fast.ids.length?'data-forest-resume':''}>${s.fast?.round&&s.fast.index<s.fast.ids.length?'5問のつづき':'森を育てる5問'} →</button><small>何回でも育つよ。まちがえても、確かめれば一歩。</small></section>`;}
export function bindForestStarts({app,cards,mutate}){app.querySelectorAll('[data-forest-start]').forEach(b=>b.onclick=async()=>{if(b.hasAttribute('data-forest-resume')){location.hash='fast';return;}const {startForestRound}=await import('./fast.js');await mutate(s=>startForestRound(s,cards,b.dataset.forestStart));location.hash='fast';});}
export function forestReward(s){const j=forestJourney(s);return `<section class="forest-reward"><h2>森に、がんばりが届いたよ！</h2>${forestSummary(s)}<p>${j.local>=16?'花咲く木が育ったね。あと'+(100-j.total%100)+'問で隣の森へ。':'木の次の姿まで、あと'+j.untilTree+'問。'}</p><a href="#forest">育った森を見に行く →</a></section>`;}
let viewingArea=null,chosenDecoration=null;
export function renderForest(ctx){const {app,state,mutate}=ctx,j=forestJourney(state);let area=Math.min(viewingArea??j.area,j.area),selected=chosenDecoration||decorations.find(d=>d.rounds<=j.rounds)?.id;
 const draw=()=>{app.innerHTML=`<div class="narrow forest-page"><a href="#home">← 学習にもどる</a><small class="eyebrow">YOUR ENGLISH FOREST</small><h1>わたしの英語の森</h1><p>学んだ分だけ、少しずつにぎやかに。</p><div id="forest-landscape">${forestScene(state,area)}</div><div class="forest-area-nav"><button id="forest-prev" ${area===0?'disabled':''}>← 前の森</button><strong>${area+1}番目の森${area<j.area?' · 完成！':''}</strong><button id="forest-next" ${area===j.area?'disabled':''}>次の森 →</button></div>${forestSummary(state)}<div class="actions"><button class="primary" data-forest-start="read">新しい5問で育てる</button><button data-forest-start="listen">聞く5問</button><button data-forest-start="weak">苦手の5問</button><a href="#karuta">音声かるたへ</a></div><section class="panel"><h2>森をかざろう</h2><p>${j.rounds?'飾りを選んで、置く場所をタップ。何度でも置きかえられるよ。':'5問チャレンジすると、小さな花が使えるよ。'}</p><div class="forest-palette">${decorations.map(d=>`<button data-decoration="${d.id}" aria-pressed="${selected===d.id}" ${d.rounds>j.rounds?'disabled':''}>${asset(d.id)}${d.name}<small>${d.rounds>j.rounds?'水あと'+(d.rounds-j.rounds)+'回':'使えるよ'}</small></button>`).join('')}</div><div class="forest-slots">${Array.from({length:6},(_,i)=>`<button data-slot="${i}" ${selected?'':'disabled'}>${state.forest?.decor[`${area}:${i}`]?asset(state.forest.decor[`${area}:${i}`]):'＋'}<small>場所${i+1}</small></button>`).join('')}</div></section><section class="panel"><h2>森の育ち方</h2><p>5問ごとに水と3スター。20問で木が次の姿に育ち、40問で池、60問でウサギ、80問でリスが登場。100問で隣の森が広がるよ。</p><p>前にまちがえた問題を自力で正解すると、花の記録が増えるよ。読む・聞くなど違う力を使っても花が咲くよ。</p><p>カードの確認・問題・かるた・実戦テストで育つよ。「飛ばす」だけでは水は増えません。休んでも森はそのまま。いつでも続きから。</p><small>森とスターは挑戦の記録。XPや準備度は、自力で答えた学習記録から計算します。</small></section><a href="#companion">森のともだちの着せ替え →</a></div>`;
 bindForestStarts(ctx);app.querySelector('#forest-prev').onclick=()=>{area--;viewingArea=area;draw();};app.querySelector('#forest-next').onclick=()=>{area++;viewingArea=area;draw();};app.querySelectorAll('[data-decoration]').forEach(b=>b.onclick=()=>{selected=b.dataset.decoration;chosenDecoration=selected;draw();});app.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>mutate(s=>decorateForest(s,area,+b.dataset.slot,selected)));};draw();
}
